import{_t as e,it as t,n,rt as r}from"./chunks/framework.D2cFUyj2.js";var i=JSON.parse(`{"title":"Space Analyzer","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Accessing Space Analyzer","slug":"_1-accessing-space-analyzer","link":"#_1-accessing-space-analyzer","children":[]},{"level":2,"title":"2. Layout & Visual Overview","slug":"_2-layout-visual-overview","link":"#_2-layout-visual-overview","children":[{"level":3,"title":"Left Pane: Treemap Visualization","slug":"left-pane-treemap-visualization","link":"#left-pane-treemap-visualization","children":[]},{"level":3,"title":"Right Pane: Sorted Size Breakdown","slug":"right-pane-sorted-size-breakdown","link":"#right-pane-sorted-size-breakdown","children":[]}]},{"level":2,"title":"3. Navigation & Context Operations","slug":"_3-navigation-context-operations","link":"#_3-navigation-context-operations","children":[]},{"level":2,"title":"4. Metrics Scope & Real-Time Sync","slug":"_4-metrics-scope-real-time-sync","link":"#_4-metrics-scope-real-time-sync","children":[{"level":3,"title":"Scope & Size Calculations","slug":"scope-size-calculations","link":"#scope-size-calculations","children":[]},{"level":3,"title":"Real-Time Change Tracking & Self-Healing","slug":"real-time-change-tracking-self-healing","link":"#real-time-change-tracking-self-healing","children":[]}]}],"relativePath":"user-guide/space-analyzer.md","filePath":"user-guide/space-analyzer.md","lastUpdated":1791379080000}`),a={name:`user-guide/space-analyzer.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="space-analyzer" tabindex="-1">Space Analyzer <a class="header-anchor" href="#space-analyzer" aria-label="Permalink to “Space Analyzer”">​</a></h1><p>Lertaro includes a disk and directory <strong>Space Analyzer</strong>. Unlike traditional disk analyzers that require lengthy physical drive scans, it leverages Lertaro&#39;s existing in-memory index tree to render storage breakdowns in seconds — even on drives hosting millions of files.</p><h2 id="_1-accessing-space-analyzer" tabindex="-1">1. Accessing Space Analyzer <a class="header-anchor" href="#_1-accessing-space-analyzer" aria-label="Permalink to “1. Accessing Space Analyzer”">​</a></h2><ul><li><strong>Automatic Presentation</strong>: Open the Full Search Window (<code>Ctrl+F</code>) with an <strong>empty search box</strong>; Space Analyzer appears automatically as the default home view.</li><li><strong>Instant Transition</strong>: Typing any character in the search box switches right away to the search results list; clearing the search box returns to the Space Analyzer view.</li></ul><h2 id="_2-layout-visual-overview" tabindex="-1">2. Layout &amp; Visual Overview <a class="header-anchor" href="#_2-layout-visual-overview" aria-label="Permalink to “2. Layout &amp; Visual Overview”">​</a></h2><p>Space Analyzer uses a dual-pane layout designed to provide immediate clarity on storage usage:</p><h3 id="left-pane-treemap-visualization" tabindex="-1">Left Pane: Treemap Visualization <a class="header-anchor" href="#left-pane-treemap-visualization" aria-label="Permalink to “Left Pane: Treemap Visualization”">​</a></h3><ul><li><strong>Proportional Area</strong>: Larger rectangles correspond to folders or files occupying more storage.</li><li><strong>Color &amp; Shade Depth</strong>: Shading reflects relative size weight within the current parent directory, with distinct borders differentiating folders from individual files.</li></ul><h3 id="right-pane-sorted-size-breakdown" tabindex="-1">Right Pane: Sorted Size Breakdown <a class="header-anchor" href="#right-pane-sorted-size-breakdown" aria-label="Permalink to “Right Pane: Sorted Size Breakdown”">​</a></h3><ul><li><strong>Descending Order</strong>: Lists child items sorted by size from largest to smallest, making storage hogs immediately identifiable.</li><li><strong>Percentage Progress Bar</strong>: Each row features a subtle proportion bar indicating its share of total visible storage.</li><li><strong>Bidirectional Highlighting</strong>: Selecting an item in the Treemap or the right-hand list synchronizes focus across both panes.</li><li><strong>Smooth Name Scrolling</strong>: Truncated long names scroll smoothly on hover or selection, replacing disruptive tooltip popups.</li></ul><h2 id="_3-navigation-context-operations" tabindex="-1">3. Navigation &amp; Context Operations <a class="header-anchor" href="#_3-navigation-context-operations" aria-label="Permalink to “3. Navigation &amp; Context Operations”">​</a></h2><ul><li><strong>Drill Down &amp; Navigate</strong>: <ul><li><strong>Enter Subdirectory</strong>: Double-left-click any Treemap card or list item to drill down into that directory.</li><li><strong>Navigate Up</strong>: Click the &quot;Up&quot; arrow in the top navigation bar, or click any parent segment in the breadcrumb path.</li></ul></li><li><strong>Context Action Menu</strong>: Right-click any card or row to open the standard <strong>Action Menu</strong> (Open, Copy Full Path, Reveal in Explorer, Recycle, or Permanent Delete).</li><li><strong>Reveal with Middle-click</strong>: Middle-click any item to reveal and locate it directly in your configured file manager.</li><li><strong>Live Preview Sync</strong>: Press <code>Alt+P</code> to open the QuickLook preview panel; the preview dynamically updates as you navigate across items.</li></ul><h2 id="_4-metrics-scope-real-time-sync" tabindex="-1">4. Metrics Scope &amp; Real-Time Sync <a class="header-anchor" href="#_4-metrics-scope-real-time-sync" aria-label="Permalink to “4. Metrics Scope &amp; Real-Time Sync”">​</a></h2><h3 id="scope-size-calculations" tabindex="-1">Scope &amp; Size Calculations <a class="header-anchor" href="#scope-size-calculations" aria-label="Permalink to “Scope &amp; Size Calculations”">​</a></h3><ul><li><strong>Index-Backed Breakdown</strong>: Summarizes items already indexed by Lertaro without initiating disk I/O crawls. Excluded files do not count toward totals.</li><li><strong>Logical File Sizes</strong>: Shows actual logical file sizes; hard-linked data is counted once to prevent inflated sizes.</li><li><strong>Access &amp; Totals</strong>: The list shows only items accessible to the current account. Directory totals describe indexed content, including inaccessible descendants. Access checks cover the requested directory and listed items without opening every descendant to calculate its size.</li><li><strong>Hidden &amp; System Items</strong>: Hidden items are included normally; system files are merged into their parent folder&#39;s total size.</li></ul><h3 id="real-time-change-tracking-self-healing" tabindex="-1">Real-Time Change Tracking &amp; Self-Healing <a class="header-anchor" href="#real-time-change-tracking-self-healing" aria-label="Permalink to “Real-Time Change Tracking &amp; Self-Healing”">​</a></h3><ul><li><strong>Live Change Updates</strong>: Receives filesystem change notifications from the background index service, debouncing updates smoothly.</li><li><strong>Self-Healing Path Fallback</strong>: If the active directory is renamed, deleted, or removed from indexing, Space Analyzer steps back automatically to the nearest valid parent folder without crashing.</li></ul>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};